window.QUESTY_PACKS = window.QUESTY_PACKS || [];
window.QUESTY_PACKS.push({"id":"nety-spec","name":"Nety spec","src":"making-of · nety-spec interviews","dot":"#2f6bff","cat":"making-of","a":[{"id":"nety-spec_q1","cat":"Brief","hat":"make","q":"What are we designing?","o":["A flove app/demo — A piece of your flove ecosystem, following its design standards.","A standalone page — A self-contained page unrelated to flove.","A single component — One focused UI piece."],"a":"A flove app/demo","pre":["A flove app/demo — A piece of your flove ecosystem, following its design standards."]},{"id":"nety-spec_q2","cat":"Brief","hat":"make","q":"Aesthetic direction?","o":["Let the assistant choose — Commit to a bold, context-fit direction with reasoning.","Minimal / refined — Restraint, precision, generous negative space.","Maximalist / bold — Dense, expressive, heavy motion, grid-breaking.","Retro / editorial — Magazine, retro-futuristic or art-deco character."],"a":"Maximalist / bold","pre":["Maximalist / bold — Dense, expressive, heavy motion, grid-breaking."]},{"id":"nety-spec_q3","cat":"Brief","hat":"make","q":"Scope on nety.html?","o":["Bold redesign, same content — Keep all existing content; push the visual language hard.","Redesign one section — Make just one zone dramatically bolder.","Add a new section — Keep the page; add a maximalist new section.","Start fresh — Throw out the layout, build anew."],"a":"Bold redesign, same content","pre":["Bold redesign, same content — Keep all existing content; push the visual language hard."]},{"id":"nety-spec_q4","cat":"Brief","hat":"make","q":"JS budget on nety?","o":["CSS-pure except ONE small inline script — Everything CSS :has()/checkbox driven, except one basic-tier script for the registration form + stars/stage state (live outputs). The agreed stance.","Fully CSS-pure, zero JS — No scripts at all; outputs are preset/illustrative, can't echo typed input.","Liberal JS — A full JS app; abandons the CSS-pure ethos."],"a":"CSS-pure except ONE small inline script","pre":["CSS-pure except ONE small inline script — Everything CSS :has()/checkbox driven, except one basic-tier script for the registration form + stars/stage state (live outputs). The agreed stance."]},{"id":"nety-spec_q5","cat":"Brief","hat":"make","q":"Which maximalist direction?","o":["Kinetic Mesh — The page IS the network: living constellation of orbiting nodes + link-lines, glowing glass cards, giant NETY.","Brutalist Terminal — Raw mono, exposed grid, hacker-manifesto energy.","Editorial Poster — Swiss-magazine: giant diagonal type, asymmetric grid, big numerals."],"a":"Kinetic Mesh","pre":["Kinetic Mesh — The page IS the network: living constellation of orbiting nodes + link-lines, glowing glass cards, giant NETY."]},{"id":"nety-spec_q6","cat":"Access","hat":"risk","q":"How to frame new features vs what's actually real?","o":["Honest status badges — Tag each capability live/partial/planned, keeping credibility.","Aspirational vision — Show the full intended experience, no caveats.","Vision now, one honesty line — Show the full vision boldly + a single candid line on preview-vs-live. Best of both."],"a":"Vision now, one honesty line","pre":["Vision now, one honesty line — Show the full vision boldly + a single candid line on preview-vs-live. Best of both."]},{"id":"nety-spec_q7","cat":"Access","hat":"risk","q":"The 'sety' settings page + profily?","o":["New top-level sety + polish profily — Create an ecosystem account page + improve profily.","Use existing puzzy/sety.html — Integrate the existing Puzzy settings page (already on nety's palette), improved.","Just profily for now — Skip settings this round."],"a":"Use existing puzzy/sety.html","pre":["Use existing puzzy/sety.html — Integrate the existing Puzzy settings page (already on nety's palette), improved."]},{"id":"nety-spec_q8","cat":"Access","hat":"risk","q":"wizy.html / the athen-ia finetuner agents?","o":["New wizy.html + surface in sety — Build a new athenea (navy+gold) agents app AND make the agents prominent in sety.","Only enhance sety's Wizard — No new page; just brand/expand the existing Wizard section.","New wizy.html only — Build the app; leave sety as-is."],"a":"New wizy.html + surface in sety","pre":["New wizy.html + surface in sety — Build a new athenea (navy+gold) agents app AND make the agents prominent in sety."]},{"id":"nety-spec_q9","cat":"Trust","hat":"risk","q":"Which signals feed a peer's trust score?","o":["Linked identities — Verified Telegram/phone/email/biometrics + self-asserted social links.","Vouches received — Weighted by the voucher's own score (transitive).","Resources shared — Compute/storage/AI contributed over time.","Invite-graph position — Branch depth/breadth + your inviter's standing."],"a":"Linked identities · Vouches received · Resources shared · Invite-graph position","pre":["Linked identities — Verified Telegram/phone/email/biometrics + self-asserted social links.","Vouches received — Weighted by the voucher's own score (transitive).","Resources shared — Compute/storage/AI contributed over time.","Invite-graph position — Branch depth/breadth + your inviter's standing."]},{"id":"nety-spec_q10","cat":"Trust","hat":"risk","q":"Can a trust score go down?","o":["Dynamic (can drop) — Inactivity-free, but abuse/slashing + transitive drops can lower it. Living standing.","Only grows — Permanent once earned; simpler but lets bad/dormant actors keep high trust.","Grows, but slashable — Accumulates, but specific events can slash it."],"a":"Dynamic (can drop)","pre":["Dynamic (can drop) — Inactivity-free, but abuse/slashing + transitive drops can lower it. Living standing."]},{"id":"nety-spec_q11","cat":"Trust","hat":"risk","q":"One number or multiple facets?","o":["Multi-facet — Several sub-scores; different capabilities gate on different facets.","Single scalar — One blended number; simplest but can't distinguish kinds of standing.","Scalar + visible breakdown — One headline number, contributing parts shown."],"a":"Multi-facet","pre":["Multi-facet — Several sub-scores; different capabilities gate on different facets."]},{"id":"nety-spec_q12","cat":"Trust","hat":"risk","q":"How do stars (currency) relate to trust score (standing)?","o":["Independent axes — Stars earned/spent; score gates. Share inputs, distinct.","Stars flow from score — Your standing sets the star MINT-RATE; spending never lowers standing. Tap vs bucket.","Unified pool — One quantity does both; spending lowers standing until re-earned."],"a":"Stars flow from score","pre":["Stars flow from score — Your standing sets the star MINT-RATE; spending never lowers standing. Tap vs bucket."]},{"id":"nety-spec_q13","cat":"Trust","hat":"risk","q":"Receiving vs giving trust?","o":["Giving is +0 direct — You gain standing only from what others extend to you; no trust-farming. Giving well compounds, giving badly costs.","Small reward for giving — A tiny bump for participating; more game-able."],"a":"Giving is +0 direct","pre":["Giving is +0 direct — You gain standing only from what others extend to you; no trust-farming. Giving well compounds, giving badly costs."]},{"id":"nety-spec_q14","cat":"Invites","hat":"heart","q":"Invite budget model?","o":["Scales with Social facet — Allowance grows with standing; Sybil-resistant.","Fixed small allotment — Everyone gets the same few; egalitarian but flat.","Earned per good invite — More invites as your invitees mature.","Scales + accountability — Scales with standing AND invitees' fates reflect back — invite someone who's slashed, your budget+score drop."],"a":"Scales + accountability","pre":["Scales + accountability — Scales with standing AND invitees' fates reflect back — invite someone who's slashed, your budget+score drop."]},{"id":"nety-spec_q15","cat":"Invites","hat":"heart","q":"How does abuse become a slash?","o":["Weighted peer reports — Reports weighted by reporter's score auto-slash; needs anti-brigading.","Reports + trusted jurors — A quorum of high-trust jurors confirms; harder to brigade.","Staked reports — Reporting costs staked stars; false reports burn the stake.","Defer — just show the slash — Mock only shows 'reported→slashed'; design real adjudication later."],"a":"Defer — just show the slash","pre":["Defer — just show the slash — Mock only shows 'reported→slashed'; design real adjudication later."]},{"id":"nety-spec_q16","cat":"Invites","hat":"heart","q":"Shape of the invite web?","o":["Multi-sponsor web (DAG) — A peer can be co-vouched by several; stronger entry.","Strict tree (one sponsor) — Exactly one inviter each; clean accountability.","Tree entry, web later — Enter via ONE invite (clean lineage tree), then accumulate vouches that add web edges for scoring without changing your parent."],"a":"Tree entry, web later","pre":["Tree entry, web later — Enter via ONE invite (clean lineage tree), then accumulate vouches that add web edges for scoring without changing your parent."]},{"id":"nety-spec_q17","cat":"Invites","hat":"heart","q":"Invite code issuance?","o":["Single-use only — One code → one person, pre-committed.","Reusable capped link — One link good for N joins.","Both (multi-use needs per-registrant validation) — Single-use code OR a capped multi-use link where you approve each registrant before they're in."],"a":"Both (multi-use needs per-registrant validation)","pre":["Both (multi-use needs per-registrant validation) — Single-use code OR a capped multi-use link where you approve each registrant before they're in."]},{"id":"nety-spec_q18","cat":"Invites","hat":"heart","q":"Revocation?","o":["Revoke unused only — Refund before use; joined lineage is permanent.","Revoke + disown — Also sever a joined invitee — costs Social score + leaves a public 'disowned' mark.","No revocation — Immutable once created."],"a":"Revoke + disown","pre":["Revoke + disown — Also sever a joined invitee — costs Social score + leaves a public 'disowned' mark."]},{"id":"nety-spec_q19","cat":"Invites","hat":"heart","q":"Invite-graph scoring: depth vs breadth?","o":["Favor depth — Deep thriving lineage is the strongest, hardest-to-fake signal.","Balance both — Wide-and-good scores like deep-and-narrow; steeper decay, higher breadth cap.","Favor breadth — Reward many good direct invitees; more gameable."],"a":"Balance both","pre":["Balance both — Wide-and-good scores like deep-and-narrow; steeper decay, higher breadth cap."]},{"id":"nety-spec_q20","cat":"Invites","hat":"heart","q":"What makes an invitee 'matured' (counts for subtree credit)?","o":["Independent verify + outside vouch — ≥ Telegram-verified on their own AND ≥1 vouch from someone OTHER than their inviter — so sponsors can't self-manufacture matured nodes.","Score threshold + time — Reach a min score sustained for a period; still gameable.","Contribution-based — Must have actually contributed/published."],"a":"Independent verify + outside vouch","pre":["Independent verify + outside vouch — ≥ Telegram-verified on their own AND ≥1 vouch from someone OTHER than their inviter — so sponsors can't self-manufacture matured nodes."]},{"id":"nety-spec_q21","cat":"Invites","hat":"heart","q":"Resisting mutual-vouch rings / collusion?","o":["Diversity-weighted vouches — A vouch counts less from your own dense cluster, full from distant independent peers — rings self-cancel.","Reciprocity discount only — Just down-weight directly mutual A↔B; misses 3+ rings.","Defer it — Note as a limitation; rely on maturation + slashing for now."],"a":"Diversity-weighted vouches","pre":["Diversity-weighted vouches — A vouch counts less from your own dense cluster, full from distant independent peers — rings self-cancel."]},{"id":"nety-spec_q22","cat":"Invites","hat":"heart","q":"Slash severity & reach?","o":["Graduated + bounded cascade — Severity scales with the offense; cascades to inviter/vouchers but decayed and only to those who didn't disown in time. Proportional.","Hard reset, no cascade — Zero the facet, contained to the offender; removes accountability pressure.","Flat penalty + full cascade — Fixed slash propagated undecayed to all ancestors; harsh, collateral-heavy."],"a":"Graduated + bounded cascade","pre":["Graduated + bounded cascade — Severity scales with the offense; cascades to inviter/vouchers but decayed and only to those who didn't disown in time. Proportional."]},{"id":"nety-spec_q23","cat":"Invites","hat":"heart","q":"Who signs the invite-lineage edge (builds the public tree)?","o":["Co-signed by both — Inviter + invitee both sign — mutual, non-repudiable, hard to forge or deny.","Inviter publishes — Ties to budget, but invitee hasn't attested their own lineage.","Invitee publishes — Natural in a feed model, but a parent could be falsely claimed."],"a":"Co-signed by both","pre":["Co-signed by both — Inviter + invitee both sign — mutual, non-repudiable, hard to forge or deny."]},{"id":"nety-spec_q24","cat":"Identity","hat":"risk","q":"Multi-use-link validation expiry?","o":["72h then auto-lapse — Pending request expires after ~3 days; time to act without strangers hanging.","7 days + reminder — Longer window with a nudge.","No expiry — manual — Sits in your queue until you act."],"a":"72h then auto-lapse","pre":["72h then auto-lapse — Pending request expires after ~3 days; time to act without strangers hanging."]},{"id":"nety-spec_q25","cat":"Identity","hat":"risk","q":"Inactivity & decay?","o":["Slow grace then steady — No decay for ~30 days idle, then gentle decline.","Gentle continuous — Always decaying slightly; penalizes brief absences.","Half-life — Each facet decays toward a floor on a fixed half-life.","Separate Activity stat (not decay) — Earned standing NEVER erodes from idleness; recency is a separate stat instead."],"a":"Separate Activity stat (not decay)","pre":["Separate Activity stat (not decay) — Earned standing NEVER erodes from idleness; recency is a separate stat instead."]},{"id":"nety-spec_q26","cat":"Identity","hat":"risk","q":"What is the top 'Biometrics' identity rung?","o":["Privacy-preserving proof-of-uniqueness — Liveness → non-reversible one-per-person token; raw biometrics never stored. No honeypot, FOSS-aligned.","Device biometric unlock — WebAuthn-style; proves device control, not one-human-one-account.","Defer the method — Keep biometrics top conceptually; pin the mechanism later."],"a":"Privacy-preserving proof-of-uniqueness","pre":["Privacy-preserving proof-of-uniqueness — Liveness → non-reversible one-per-person token; raw biometrics never stored. No honeypot, FOSS-aligned."]},{"id":"nety-spec_q27","cat":"Identity","hat":"risk","q":"What is the Activity stat?","o":["A visible presence signal, inside Global — Purely a public liveness indicator; gates nothing, changes no scores. Lives as the presence dimension of the Global facet.","A scored factor — Activity feeds standing/perks (e.g. mint-rate).","A separate fifth stat — Its own top-level stat, outside the four facets."],"a":"A visible presence signal, inside Global","pre":["A visible presence signal, inside Global — Purely a public liveness indicator; gates nothing, changes no scores. Lives as the presence dimension of the Global facet."]},{"id":"nety-spec_q28","cat":"Identity","hat":"risk","q":"Presence model for an offline-first P2P node?","o":["Graded LIVE / RECENT / REACHABLE / DARK — LIVE=online now; RECENT=acted lately; REACHABLE=offline but content replicated by peers; DARK=neither. Honest: offline ≠ unreachable.","Just live heartbeat — Online-now bit; misleading when a dark node's content is still served.","Last meaningful action — Just a timestamp; ignores reachability."],"a":"Graded LIVE / RECENT / REACHABLE / DARK","pre":["Graded LIVE / RECENT / REACHABLE / DARK — LIVE=online now; RECENT=acted lately; REACHABLE=offline but content replicated by peers; DARK=neither. Honest: offline ≠ unreachable."]},{"id":"nety-spec_q29","cat":"Circles","hat":"make","q":"What does the permissions layer govern?","o":["Content / pages — Who can read your published pages, posts, files.","Shared resources — Who can draw on the compute/storage/AI you offer.","Profile data — Field-level visibility of your profily.","Interaction / social — Who can message you, request to join via you, add you to their MyNet."],"a":"Content / pages · Shared resources · Profile data · Interaction / social","pre":["Content / pages — Who can read your published pages, posts, files.","Shared resources — Who can draw on the compute/storage/AI you offer.","Profile data — Field-level visibility of your profily.","Interaction / social — Who can message you, request to join via you, add you to their MyNet."]},{"id":"nety-spec_q30","cat":"Circles","hat":"make","q":"What are permissions granted to?","o":["MyNet + named circles — Your whole MyNet and/or named sub-circles. Most expressive.","Per-peer only — Individual grant/deny; precise but tedious.","By trust tier — Grant by network trust level; leans on the score.","Hybrid: circles + tiers — Circles AND tiers in one rule."],"a":"MyNet + named circles","pre":["MyNet + named circles — Your whole MyNet and/or named sub-circles. Most expressive."]},{"id":"nety-spec_q31","cat":"Circles","hat":"make","q":"Default audience for a new peer?","o":["Private-first, opt-in to share — Everything starts private; you deliberately widen each area. Safest, FOSS-aligned.","Sensible per-area defaults — Reasonable defaults per area; friendlier but some things visible early.","Public-first, opt-in to restrict — Open by default; lock down what you want private."],"a":"Private-first, opt-in to share","pre":["Private-first, opt-in to share — Everything starts private; you deliberately widen each area. Safest, FOSS-aligned."]},{"id":"nety-spec_q32","cat":"Circles","hat":"make","q":"Circle model?","o":["Flat subsets of MyNet — Each circle a subset; a peer in several; no nesting.","Nested tiers — Concentric rings close⊆friends⊆MyNet; outer grant includes inner.","Flat independent tags — Labels with no MyNet relationship; can include non-MyNet peers.","Nested tiers + independent tags (both) — Tiered rings for graded trust AND flat tag circles for project/context groups, coexisting."],"a":"Nested tiers + independent tags (both)","pre":["Nested tiers + independent tags (both) — Tiered rings for graded trust AND flat tag circles for project/context groups, coexisting."]},{"id":"nety-spec_q33","cat":"Circles","hat":"make","q":"Which layers do circles span?","o":["Both nety + appy, parallel & connectable — nety circles and appy circles are the same circles, running in parallel and easily linked across the bridge.","Upper (appy) only — Circles live only in the apps layer.","Lower (nety) only — Circles live only in the infrastructure layer."],"a":"Both nety + appy, parallel & connectable","pre":["Both nety + appy, parallel & connectable — nety circles and appy circles are the same circles, running in parallel and easily linked across the bridge."]},{"id":"nety-spec_q34","cat":"Circles","hat":"make","q":"How visible are your facet scores to others?","o":["Owner-controlled per facet — Default private; you reveal each facet (exact or coarse tier) to public/MyNet/circles. The protocol still computes with true scores.","Public tier badges, exact private — Others see coarse tiers; exact numbers private to you.","Fully public exact — All four facet values visible to everyone.","Fully private — Nobody sees scores; only capability outcomes observable."],"a":"Owner-controlled per facet","pre":["Owner-controlled per facet — Default private; you reveal each facet (exact or coarse tier) to public/MyNet/circles. The protocol still computes with true scores."]},{"id":"nety-spec_q35","cat":"Economy","hat":"optimism","q":"Free-vs-stars posture (flove is FOSS)?","o":["Passwords granted at contributing stages — As you accomplish contribution STAGES you're granted passwords that unlock protected page-sections. Access earned by contributing, not bought.","Apps free; stars unlock scale/premium — Apps free; stars unlock resource-heavy capabilities only.","Tiered free core + star-gated apps — Most apps free; some need a star unlock.","Stars unlock each app — Each app costs stars to open; least FOSS-aligned."],"a":"Passwords granted at contributing stages","pre":["Passwords granted at contributing stages — As you accomplish contribution STAGES you're granted passwords that unlock protected page-sections. Access earned by contributing, not bought."]},{"id":"nety-spec_q36","cat":"Economy","hat":"optimism","q":"Unlock model?","o":["One-time, owned forever — Reach a stage once, keep the access permanently.","Metered / pay-as-you-go — Spend per use of a heavy capability.","Subscription — Recurring cost to keep a capability; least aligned."],"a":"One-time, owned forever","pre":["One-time, owned forever — Reach a stage once, keep the access permanently."]},{"id":"nety-spec_q37","cat":"Economy","hat":"optimism","q":"What advances you through stages?","o":["Contribution, gated by trust floors — Contribution-driven, but sensitive stages (donation-directing, top tier) need a minimum trust floor — no advancing by raw resource-dumping.","Contribution-only — Pure contribution milestones; clean separation.","Blended contribution + standing — Every stage needs both contribution and a tier."],"a":"Contribution, gated by trust floors","pre":["Contribution, gated by trust floors — Contribution-driven, but sensitive stages (donation-directing, top tier) need a minimum trust floor — no advancing by raw resource-dumping."]},{"id":"nety-spec_q38","cat":"Economy","hat":"optimism","q":"Donation directing — what can you direct?","o":["Both (earmark own + steward pool) — Earmark your own contributions early; steward the shared pool at expert+.","Steward the shared commons — Allocate the pooled/donated commons; high-trust power.","Earmark your own — Direct only what you contribute."],"a":"Both (earmark own + steward pool)","pre":["Both (earmark own + steward pool) — Earmark your own contributions early; steward the shared pool at expert+."]},{"id":"nety-spec_q39","cat":"Economy","hat":"optimism","q":"Directing — standing policy or per-donation?","o":["Standing default + per-donation override — Set a default ('mostly to close'), override on any single donation.","Standing policy only — One policy until changed; set-and-forget.","Per-donation only — Direct each donation explicitly; more friction."],"a":"Standing default + per-donation override","pre":["Standing default + per-donation override — Set a default ('mostly to close'), override on any single donation."]},{"id":"nety-spec_q40","cat":"Economy","hat":"optimism","q":"In 'only' mode, if the target can't absorb it?","o":["Fall back to the shared pool — Surplus flows to the commons rather than sitting idle; softens 'only' but never wastes.","Hold / queue for the target — Waits until the target can use it; strict.","Return to donor — Reverts to you to redirect."],"a":"Fall back to the shared pool","pre":["Fall back to the shared pool — Surplus flows to the commons rather than sitting idle; softens 'only' but never wastes."]},{"id":"nety-spec_q41","cat":"Economy","hat":"optimism","q":"Directing transparency?","o":["Donor decides — Each donor sets per-donation: public ledger / contributor-visible / private. A steward can't override it.","Public ledger — All directing visible; max accountability.","known-visible — Only pool contributors see allocation.","Private — Allocation not surfaced."],"a":"Donor decides","pre":["Donor decides — Each donor sets per-donation: public ledger / contributor-visible / private. A steward can't override it."]},{"id":"nety-spec_q42","cat":"Economy","hat":"optimism","q":"How does the donation pool fill?","o":["Purely voluntary — Only what peers explicitly donate; most free-as-in-freedom, may be thin.","Voluntary + small auto-tithe — Mostly voluntary + ~2–5% tithe so the pool always exists.","Surplus / unclaimed flows in — Idle offered resources auto-flow to the pool.","Voluntary + surplus — Explicit donations + idle surplus, no tithe on used resources."],"a":"Purely voluntary","pre":["Purely voluntary — Only what peers explicitly donate; most free-as-in-freedom, may be thin."]},{"id":"nety-spec_q43","cat":"Cross-cutting","hat":"make","q":"How does nety standing carry into the apps?","o":["Portable base + per-app overlay — Your four facets/stage/presence port everywhere as the baseline; each app can add its own context reputation on top.","One global score everywhere — Apps read one standing; consistent but flattens kinds of merit.","Per-community scoped — Each app weights/holds its own trust; less portable."],"a":"Portable base + per-app overlay","pre":["Portable base + per-app overlay — Your four facets/stage/presence port everywhere as the baseline; each app can add its own context reputation on top."]},{"id":"nety-spec_q44","cat":"Cross-cutting","hat":"make","q":"MyWizy autonomy (the finetuner)?","o":["You set policy, agent optimizes within it — You set goals + hard budgets/privacy; MyWizy optimizes peering/relay/recs within bounds and explains its choices.","Fully manual, agent only suggests — You set everything; it just recommends.","Fully autonomous, you set a vibe — Pick a mode; it handles the rest."],"a":"You set policy, agent optimizes within it","pre":["You set policy, agent optimizes within it — You set goals + hard budgets/privacy; MyWizy optimizes peering/relay/recs within bounds and explains its choices."]},{"id":"nety-spec_q45","cat":"Cross-cutting","hat":"make","q":"Key loss recovery?","o":["Self-backup + social fallback — You hold a backup to rotate yourself; if lost, a quorum of your MyNet/vouchers co-signs to rebind.","Social recovery only — Always a trusted-quorum rebind; nothing to store, depends on peers.","Self-custody only — You alone hold a backup; lose it, lose everything."],"a":"Self-backup + social fallback","pre":["Self-backup + social fallback — You hold a backup to rotate yourself; if lost, a quorum of your MyNet/vouchers co-signs to rebind."]},{"id":"nety-spec_q46","cat":"Cross-cutting","hat":"make","q":"Standing transfer on recovery?","o":["Carries forward, brief probation — All standing transfers, but a short probation after SOCIAL recovery guards against a hijacked recovery.","Carries forward fully — New key inherits everything immediately; key-change shown on the tree.","Lineage yes, scores partial — Identity+lineage survive, some scores re-accrue."],"a":"Carries forward, brief probation","pre":["Carries forward, brief probation — All standing transfers, but a short probation after SOCIAL recovery guards against a hijacked recovery."]},{"id":"nety-spec_q47","cat":"Cross-cutting","hat":"make","q":"How does the Verify trust section render?","o":["Concentric scope rings — Nested rings Personal(core)→Local→Social→Global; arcs fill by score, Activity pulses on the outer ring. Literally draws 'concentric scope'.","Stacked meters + boards — Four labeled bars + ladder + stage board; clearest, least designed.","Orbiting facet constellation — You at center, facet-nodes orbiting; beautiful but busier."],"a":"Concentric scope rings","pre":["Concentric scope rings — Nested rings Personal(core)→Local→Social→Global; arcs fill by score, Activity pulses on the outer ring. Literally draws 'concentric scope'."]},{"id":"nety-spec_q48","cat":"oasis","hat":"make","q":"flovenet apps vs oasis — overall stance?","o":["flovenet INDEPENDENT; oasis as optional add-on — flovenet apps implement everything natively, LEARNING oasis's good patterns; oasis is an opt-in add-on (SSB federation, '42' AI). flovenet works fully without it.","oasis as the upper layer — Build the apps layer on oasis/SSB directly; a hard dependency.","Merge into one stack — Fuse flovenet + oasis into a single codebase."],"a":"flovenet INDEPENDENT; oasis as optional add-on","pre":["flovenet INDEPENDENT; oasis as optional add-on — flovenet apps implement everything natively, LEARNING oasis's good patterns; oasis is an opt-in add-on (SSB federation, '42' AI). flovenet works fully without it."]},{"id":"nety-spec_q49","cat":"oasis","hat":"make","q":"flovenet has ONE score; spec wants four facets — reconcile?","o":["Derive four facets as views — Keep the working engine; expose four facets as derived views over inputs it already has. Least churn.","Refactor reputation_engine into 4 facets — Properly re-model into four stored scores; cleanest, most churn.","UI-only four facets — Single score under the hood; four facets only in the frontend."],"a":"Derive four facets as views","pre":["Derive four facets as views — Keep the working engine; expose four facets as derived views over inputs it already has. Least churn."]},{"id":"nety-spec_q50","cat":"oasis","hat":"make","q":"The invite layer (absent in flovenet) — build where/when?","o":["Frontend mock now + adapt oasis pub-invites later — nety page mocks the whole invite web now; real path extends oasis pub-invites with lineage. Native build is a later milestone.","Start the flovenet invite module now — Begin a real Rust invite layer in parallel.","Adapt oasis pub-invites — Base it on SSB invites from the start."],"a":"Frontend mock now + adapt oasis pub-invites later","pre":["Frontend mock now + adapt oasis pub-invites later — nety page mocks the whole invite web now; real path extends oasis pub-invites with lineage. Native build is a later milestone."]},{"id":"nety-spec_q51","cat":"oasis","hat":"make","q":"Recovery realism (SSB can't rotate identity)?","o":["Accept 'no recovery' for now — Mock recovery in the frontend; real social recovery is an acknowledged hard future milestone, not a blocker.","Commit to a social-recovery sidechain — Plan a real rotation/recovery layer beside the append-only identity.","Self-backup only for now — Ship only self-custody backup; defer social recovery."],"a":"Accept 'no recovery' for now","pre":["Accept 'no recovery' for now — Mock recovery in the frontend; real social recovery is an acknowledged hard future milestone, not a blocker."]},{"id":"nety-spec_q52","cat":"Bridge","hat":"make","q":"Should one identity span both layers?","o":["One Ed25519 keypair spans both layers — Your single key is both the flovenet keystore identity AND the (optional) SSB feed. The keypair is the unifying thread.","Separate keys + signed binding — Distinct keys linked by an attestation; more isolation, more plumbing.","Bridge at app layer only — Identities separate, associated only in the UI."],"a":"One Ed25519 keypair spans both layers","pre":["One Ed25519 keypair spans both layers — Your single key is both the flovenet keystore identity AND the (optional) SSB feed. The keypair is the unifying thread."]},{"id":"nety-spec_q53","cat":"Bridge","hat":"make","q":"How does flovenet data reach the upper layer?","o":["flovenet GraphQL gateway as the bridge — The upper layer reads the portable base (4 facets, stage, presence, resources) from flovenet's existing GraphQL gateway.","Dedicated SSB↔flovenet service — A translator service maps messages both ways; more decoupled, more work.","Frontend composes both — The frontend reads each separately; no server unification."],"a":"flovenet GraphQL gateway as the bridge","pre":["flovenet GraphQL gateway as the bridge — The upper layer reads the portable base (4 facets, stage, presence, resources) from flovenet's existing GraphQL gateway."]},{"id":"nety-spec_q54","cat":"Bridge","hat":"make","q":"Where's the authoritative trust/vouch graph?","o":["flovenet trust_graph (follows mirror it) — Vouches + facet inputs live in flovenet; SSB follows are a social mirror. One source of truth for scoring.","SSB follows authoritative, flovenet derives — Social graph in SSB; flovenet ingests to score.","Split: vouches flovenet / follows SSB — Weighted vouches in flovenet, casual follows in SSB."],"a":"flovenet trust_graph (follows mirror it)","pre":["flovenet trust_graph (follows mirror it) — Vouches + facet inputs live in flovenet; SSB follows are a social mirror. One source of truth for scoring."]},{"id":"nety-spec_q55","cat":"Native","hat":"make","q":"Native circle storage / replication?","o":["OR-Set CRDT over gossipsub — Membership as a CRDT gossiped over libp2p — reuses flovenet's existing CRDT+gossipsub stack; content encrypted to a group key.","Dedicated group protocol — A purpose-built group/channel subsystem; cleaner, more to build.","Reuse social_protocol + storage — Layer circles on existing types; least code, not first-class."],"a":"OR-Set CRDT over gossipsub","pre":["OR-Set CRDT over gossipsub — Membership as a CRDT gossiped over libp2p — reuses flovenet's existing CRDT+gossipsub stack; content encrypted to a group key."]},{"id":"nety-spec_q56","cat":"Native","hat":"make","q":"Group key when a member is removed?","o":["Rotate on removal (forward secrecy) — Re-seal a fresh key to remaining members so the removed peer can't read future content.","Static group key — One key for life; removed members keep it. No forward secrecy.","Rotate on schedule + on removal — Also epoch-rotate; most secure, most overhead."],"a":"Rotate on removal (forward secrecy)","pre":["Rotate on removal (forward secrecy) — Re-seal a fresh key to remaining members so the removed peer can't read future content."]},{"id":"nety-spec_q57","cat":"Native","hat":"make","q":"Encrypted circle posting via the oasis/SSB add-on (7-recps cap)?","o":["Private groups (box2) per circle — Each circle is an SSB private group with a shared key; scales past the ~7-recipient box1 limit.","box1 recps everywhere — Classic recps ≤7; breaks for real circles.","Re-encrypt per member — A copy per recipient; heavy and leaky."],"a":"Private groups (box2) per circle","pre":["Private groups (box2) per circle — Each circle is an SSB private group with a shared key; scales past the ~7-recipient box1 limit."]},{"id":"nety-spec_q58","cat":"Native","hat":"make","q":"SSB public posts are irreversible — UI?","o":["Treat public normally — Public is just another audience choice, no special warning.","Explicit 'permanent & public' confirm — Going public names the irreversibility; reinforces private-first.","Public = separate explicit mode — A distinct 'publish to the world' action, separated from private sharing."],"a":"Treat public normally","pre":["Treat public normally — Public is just another audience choice, no special warning."]},{"id":"nety-spec_q59","cat":"Native","hat":"make","q":"Lineage tree storage?","o":["Append-only signed records over gossipsub — Each co-signed edge gossiped + stored; tree reconstructed from edges. Immutable, traceable. (Default — not explicitly chosen.)","CRDT tree structure — Tree as a CRDT; lineage is immutable history, so append-only fits better.","Kademlia DHT records — Edges as DHT entries; weaker for full traversal."],"a":"Append-only signed records over gossipsub","pre":["Append-only signed records over gossipsub — Each co-signed edge gossiped + stored; tree reconstructed from edges. Immutable, traceable. (Default — not explicitly chosen.)"]},{"id":"nety-spec_q60","cat":"Native","hat":"make","q":"Invite-budget over-issuance with no central counter?","o":["Accept eventual-consistency drift — Don't hard-block; tolerate brief over-issuance under partition, reconcile later by slashing. Fits a P2P network.","Publicly-derivable allowance + detectable over-issuance — Anyone counts issued vs allowance; excess rejected, over-issuer slashed.","Invitee checks before accepting — Each joiner verifies the inviter's count first."],"a":"Accept eventual-consistency drift","pre":["Accept eventual-consistency drift — Don't hard-block; tolerate brief over-issuance under partition, reconcile later by slashing. Fits a P2P network."]},{"id":"nety-spec_q61","cat":"Tiers","hat":"make","q":"Names for the five stages (replacing Joined·Contributor·Steward·Patron·Pillar)?","o":["newbie · known · homie · expert · legend — Marc's chosen stage names, mapping to the mini→super tier ceilings.","mini · basic · normal · advanced · super — Reuse the tier names as stage names.","Seed · Sprout · Grove · Forest · Canopy — Organic growth metaphor."],"a":"newbie · known · homie · expert · legend","pre":["newbie · known · homie · expert · legend — Marc's chosen stage names, mapping to the mini→super tier ceilings."]},{"id":"nety-spec_q62","cat":"Tiers","hat":"make","q":"How do stages relate to the tier/mode you browse in?","o":["Stage = earned ceiling; mode is your choice (optionally activatable) — Your stage unlocks a ceiling of tiers; you freely pick any tier at/below it, new features optional. A legend can browse mini/basic. Earned level ≠ chosen mode.","Stage hard-locks you to one tier — You're always in the tier your stage dictates; no downshifting.","Fully independent — Tiers and stages unrelated."],"a":"Stage = earned ceiling; mode is your choice (optionally activatable)","pre":["Stage = earned ceiling; mode is your choice (optionally activatable) — Your stage unlocks a ceiling of tiers; you freely pick any tier at/below it, new features optional. A legend can browse mini/basic. Earned level ≠ chosen mode."]},{"id":"nety-spec_q63","cat":"Tiers","hat":"make","q":"What does the 'super' tier add?","o":["Leave super open for now — Define mini→advanced concretely; super = 'the full stack, TBD'.","Full integration of all tiers — super = everything woven together, all scopes active.","Network-wide / steward powers — super adds top-end powers (pool stewardship, governance)."],"a":"Leave super open for now","pre":["Leave super open for now — Define mini→advanced concretely; super = 'the full stack, TBD'."]},{"id":"nety-spec_q64","cat":"Tiers","hat":"make","q":"What do nety's hardware tiers add (mini→super)?","o":["Same resource types, more quota — nety is a QUOTA ladder — every tier shares the same resources; higher tiers just raise how much you contribute/draw.","Scaling capacity & new roles — Each tier adds new hardware capabilities (relay→compute→GPU→orchestration).","Leave nety tiers open — Spec the hardware ladder later."],"a":"Same resource types, more quota","pre":["Same resource types, more quota — nety is a QUOTA ladder — every tier shares the same resources; higher tiers just raise how much you contribute/draw."]},{"id":"nety-spec_q65","cat":"Tiers","hat":"make","q":"Do the nety (hardware) and appy (software) ladders advance together or apart?","o":["Independent, both feed your standing — Progress in each domain separately; hardware→Global, software→other facets. Either path raises your stage.","One linked stage — A single stage advances both domains together.","Hardware gates software — Climb nety first to unlock the matching appy tier."],"a":"Independent, both feed your standing","pre":["Independent, both feed your standing — Progress in each domain separately; hardware→Global, software→other facets. Either path raises your stage."]},{"id":"nety-spec_q66","cat":"Tiers","hat":"make","q":"Access gating: mini (nety) vs basic (appy)?","o":["mini open, basic invite-gated — Freely download the client + contribute to nety + get a web miniprofile (no invite); registering into appy (play & store apps) needs an invite.","Both open — No invite anywhere; fully permissionless.","Both invite-gated — Even running the nety client needs an invite."],"a":"mini open, basic invite-gated","pre":["mini open, basic invite-gated — Freely download the client + contribute to nety + get a web miniprofile (no invite); registering into appy (play & store apps) needs an invite."]},{"id":"nety-spec_q67","cat":"Tiers","hat":"make","q":"Can you advance without sharing nety resources?","o":["Yes — substitute more authentication/trust — Skip nety contributions but compensate with more Personal/Social/Local (identities, vouches, invites). Facets are substitutable.","No — contribution is required — You must share resources to advance."],"a":"Yes — substitute more authentication/trust","pre":["Yes — substitute more authentication/trust — Skip nety contributions but compensate with more Personal/Social/Local (identities, vouches, invites). Facets are substitutable."]},{"id":"nety-spec_q68","cat":"Notes","hat":"make","q":"Two tiered domains","o":["Two tiered domains: nety = hardware (compute/storage/AI/network resources — a QUOTA ladder: same resource types, more quota per tier) · appy = data-software (apps/data/profiles — a FEATURE ladder). Each runs mini→basic→normal→advanced→super. The two ladders advance independently and both feed your standing. Profile: profily-mini (open web miniprofile) ↔ profily (full, in appy). Circles exist in both, parallel & connectable.","Two tiered domains, separate: nety = hardware quota ladder (compute/storage/AI/network), appy = software feature ladder (apps/data/profiles)","One combined ladder covering hardware and software together","nety (hardware) gates how high appy (software) can climb"],"a":"Two tiered domains: nety = hardware (compute/storage/AI/network resources — a QUOTA ladder: same resource types, more quota per tier) · appy = data-software (apps/data/profiles — a FEATURE ladder). Each runs mini→basic→normal→advanced→super. The two ladders advance independently and both feed your standing. Profile: profily-mini (open web miniprofile) ↔ profily (full, in appy). Circles exist in both, parallel & connectable.","pre":["Two tiered domains: nety = hardware (compute/storage/AI/network resources — a QUOTA ladder: same resource types, more quota per tier) · appy = data-software (apps/data/profiles — a FEATURE ladder). Each runs mini→basic→normal→advanced→super. The two ladders advance independently and both feed your standing. Profile: profily-mini (open web miniprofile) ↔ profily (full, in appy). Circles exist in both, parallel & connectable."]},{"id":"nety-spec_q69","cat":"Notes","hat":"make","q":"Stages (newbie·known·homie·expert·legend)","o":["Stages (newbie·known·homie·expert·legend) gate the TIER CEILING you can use; the tier/mode you browse is your choice (features optionally activatable — a legend can browse mini). Advance by sharing nety hardware OR by substituting more authentication/trust. appy tiers map: mini=nety(resources)·basic=profily+apps(play & store)·normal=sety(data mgmt)·advanced=MyWizy·super=open.","Stages (newbie·known·homie·expert·legend) gate the tier ceiling; which tier you browse is your choice","Each stage hard-locks you into its own tier","Stages are cosmetic — no ceiling or gating at all"],"a":"Stages (newbie·known·homie·expert·legend) gate the TIER CEILING you can use; the tier/mode you browse is your choice (features optionally activatable — a legend can browse mini). Advance by sharing nety hardware OR by substituting more authentication/trust. appy tiers map: mini=nety(resources)·basic=profily+apps(play & store)·normal=sety(data mgmt)·advanced=MyWizy·super=open.","pre":["Stages (newbie·known·homie·expert·legend) gate the TIER CEILING you can use; the tier/mode you browse is your choice (features optionally activatable — a legend can browse mini). Advance by sharing nety hardware OR by substituting more authentication/trust. appy tiers map: mini=nety(resources)·basic=profily+apps(play & store)·normal=sety(data mgmt)·advanced=MyWizy·super=open."]},{"id":"nety-spec_q70","cat":"Notes","hat":"make","q":"Access","o":["Access: mini (nety) is open — free client + contribute + web miniprofile, no invite. basic (appy) is invite-gated — registering to play & store apps needs an invite (~3/month per user, vertical web-of-trust bootstrap).","mini (nety) open — free client + contribute + web miniprofile; basic (appy) invite-gated for play & store","Everything open and permissionless, including appy registration","Everything invite-gated, even running the nety client"],"a":"Access: mini (nety) is open — free client + contribute + web miniprofile, no invite. basic (appy) is invite-gated — registering to play & store apps needs an invite (~3/month per user, vertical web-of-trust bootstrap).","pre":["Access: mini (nety) is open — free client + contribute + web miniprofile, no invite. basic (appy) is invite-gated — registering to play & store apps needs an invite (~3/month per user, vertical web-of-trust bootstrap)."]},{"id":"nety-spec_q71","cat":"Notes","hat":"make","q":"Four scoped facets","o":["Four scoped facets (Marc's taxonomy): Personal=authentication · Local=invite-net · Social=trusts · Global=contribs. Activity (presence) lives inside Global.","Four scoped facets: Personal=auth · Local=invite-net · Social=trusts · Global=contribs; Activity (presence) inside Global","A single blended trust score instead of four facets","Four facets plus Activity as a separate fifth stat"],"a":"Four scoped facets (Marc's taxonomy): Personal=authentication · Local=invite-net · Social=trusts · Global=contribs. Activity (presence) lives inside Global.","pre":["Four scoped facets (Marc's taxonomy): Personal=authentication · Local=invite-net · Social=trusts · Global=contribs. Activity (presence) lives inside Global."]},{"id":"nety-spec_q72","cat":"Notes","hat":"make","q":"Identity rung weights","o":["Identity rung weights (low→high): social link (email-only platform) → social link (phone-required platform, e.g. idealista > Instagram) → verified email → verified Telegram ✦ publish gate → verified phone → biometrics. Only Telegram is verified for now; weight = verification rigor.","Identity rung weights low→high: social link (email-only) → social link (phone) → verified email → verified Telegram ✦ publish gate → verified phone → biometrics","All identity rungs carry equal weight","Weights stay hidden — only coarse tier badges are shown"],"a":"Identity rung weights (low→high): social link (email-only platform) → social link (phone-required platform, e.g. idealista > Instagram) → verified email → verified Telegram ✦ publish gate → verified phone → biometrics. Only Telegram is verified for now; weight = verification rigor.","pre":["Identity rung weights (low→high): social link (email-only platform) → social link (phone-required platform, e.g. idealista > Instagram) → verified email → verified Telegram ✦ publish gate → verified phone → biometrics. Only Telegram is verified for now; weight = verification rigor."]},{"id":"nety-spec_q73","cat":"Notes","hat":"make","q":"Registration is invite-coded;","o":["Registration is invite-coded; publishing a static HTML page needs ≥ Telegram verification.","Registration is invite-coded; publishing a static HTML page requires ≥ Telegram verification","Open registration; publishing still requires ≥ Telegram verification","Invite-coded registration but publishing needs no verification"],"a":"Registration is invite-coded; publishing a static HTML page needs ≥ Telegram verification.","pre":["Registration is invite-coded; publishing a static HTML page needs ≥ Telegram verification."]},{"id":"nety-spec_q74","cat":"Notes","hat":"make","q":"Store integrates","o":["Store integrates profily (extended profile) + puzzy/sety (settings) + wizy (agents).","Store integrates profily (extended profile) + puzzy/sety (settings) + wizy (agents)","Store is apps-only; profile, settings and agents stay separate apps","A single all-in-one account app replacing the three"],"a":"Store integrates profily (extended profile) + puzzy/sety (settings) + wizy (agents).","pre":["Store integrates profily (extended profile) + puzzy/sety (settings) + wizy (agents)."]},{"id":"nety-spec_q75","cat":"Notes","hat":"make","q":"MyNet","o":["MyNet spans both layers (f2f substrate in nety, custom circles in appy). MyWizy = your athen-ia finetuner (tunes f2f connectivity + apps experience); Wizy = the app.","MyNet spans both layers (f2f substrate in nety, custom circles in appy); MyWizy = your athen-ia finetuner, Wizy = the app","MyNet lives only in the upper appy layer","MyNet lives only in the lower nety infrastructure layer"],"a":"MyNet spans both layers (f2f substrate in nety, custom circles in appy). MyWizy = your athen-ia finetuner (tunes f2f connectivity + apps experience); Wizy = the app.","pre":["MyNet spans both layers (f2f substrate in nety, custom circles in appy). MyWizy = your athen-ia finetuner (tunes f2f connectivity + apps experience); Wizy = the app."]},{"id":"nety-spec_q76","cat":"Notes","hat":"make","q":"Stages unlock more across both layers","o":["Stages unlock more across both layers: further apps (upper) + further resources & donation directing (lower). Donations can target a circle ('to my close ring, mostly or only').","Stages unlock more across both layers: further apps (upper) + further resources & donation directing (lower); donations can target a circle","Stages unlock apps only — resources/donations stay flat","Stages unlock resources only — apps stay open to everyone"],"a":"Stages unlock more across both layers: further apps (upper) + further resources & donation directing (lower). Donations can target a circle ('to my close ring, mostly or only').","pre":["Stages unlock more across both layers: further apps (upper) + further resources & donation directing (lower). Donations can target a circle ('to my close ring, mostly or only')."]},{"id":"nety-spec_q77","cat":"Notes","hat":"make","q":"Invites stay public/traceable","o":["Invites stay public/traceable for flagging, even though facet scores are owner-private.","Invites stay public/traceable for flagging, even though facet scores are owner-private","Invites are private too; only scores are public","Everything about a peer is public and traceable"],"a":"Invites stay public/traceable for flagging, even though facet scores are owner-private.","pre":["Invites stay public/traceable for flagging, even though facet scores are owner-private."]},{"id":"nety-spec_q78","cat":"Notes","hat":"make","q":"GOVERNING STANCE","o":["GOVERNING STANCE: flovenet apps INDEPENDENT — implemented natively, LEARNING oasis's good patterns (private groups, follows-as-mirror, offline-first, private-first, circles). oasis = optional add-on (SSB federation, '42' as a pluggable MyWizy AI engine).","flovenet apps INDEPENDENT — implemented natively, LEARNING oasis's good patterns; oasis is an optional add-on","Build the apps layer on oasis/SSB as a hard dependency","Fuse flovenet and oasis into a single stack"],"a":"GOVERNING STANCE: flovenet apps INDEPENDENT — implemented natively, LEARNING oasis's good patterns (private groups, follows-as-mirror, offline-first, private-first, circles). oasis = optional add-on (SSB federation, '42' as a pluggable MyWizy AI engine).","pre":["GOVERNING STANCE: flovenet apps INDEPENDENT — implemented natively, LEARNING oasis's good patterns (private groups, follows-as-mirror, offline-first, private-first, circles). oasis = optional add-on (SSB federation, '42' as a pluggable MyWizy AI engine)."]},{"id":"nety-spec_q79","cat":"Notes","hat":"make","q":"Bridge","o":["Bridge: one Ed25519 keypair → flovenet (lower) → GraphQL gateway (portable base) → upper layer. 'Circles' is the user-facing name; SSB tribes only an under-the-hood primitive.","Bridge: one Ed25519 keypair → flovenet (lower) → GraphQL gateway (portable base) → upper layer; 'Circles' is the user-facing name","Separate keys per layer joined by a signed attestation","Bridge at the app layer only — identities stay fully separate"],"a":"Bridge: one Ed25519 keypair → flovenet (lower) → GraphQL gateway (portable base) → upper layer. 'Circles' is the user-facing name; SSB tribes only an under-the-hood primitive.","pre":["Bridge: one Ed25519 keypair → flovenet (lower) → GraphQL gateway (portable base) → upper layer. 'Circles' is the user-facing name; SSB tribes only an under-the-hood primitive."]},{"id":"nety-spec_q80","cat":"Notes","hat":"make","q":"MyWizy AI","o":["MyWizy AI: flovenet-native local-first by default; oasis '42' an optional pluggable engine. Deeper inference details = further spec later.","MyWizy AI: flovenet-native local-first by default; oasis '42' an optional pluggable engine","oasis '42' is the default inference engine","A hosted cloud AI service powers MyWizy"],"a":"MyWizy AI: flovenet-native local-first by default; oasis '42' an optional pluggable engine. Deeper inference details = further spec later.","pre":["MyWizy AI: flovenet-native local-first by default; oasis '42' an optional pluggable engine. Deeper inference details = further spec later."]}]});
